import os
from azure.ai.documentintelligence import DocumentIntelligenceClient
from azure.core.credentials import AzureKeyCredential

def get_document_intelligence_client():
    endpoint = os.environ.get("AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT")
    api_key = os.environ.get("AZURE_DOCUMENT_INTELLIGENCE_API_KEY")
    if not endpoint or not api_key:
        raise ValueError("AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT and AZURE_DOCUMENT_INTELLIGENCE_API_KEY must be set in environment variables.")
    return DocumentIntelligenceClient(endpoint=endpoint, credential=AzureKeyCredential(api_key))

import io
from document_client import get_document_intelligence_client

def extract_layout(payload):
    client = get_document_intelligence_client()
    with client:
        poller = client.begin_analyze_document(
            "prebuilt-layout",
            body=io.BytesIO(payload['document_bytes']), 
            content_type=payload['mime_type']
        )
        result = poller.result()

    layout_elements = {
        "paragraphs": [{
            "content": p.content,
            "bounding_regions": [{"page_number": br.page_number, "polygon": br.polygon} for br in p.bounding_regions]
        } for p in result.paragraphs],
        "tables": [{
            "row_count": t.row_count,
            "column_count": t.column_count,
            "cells": [{
                "content": c.content,
                "row_index": c.row_index,
                "column_index": c.column_index,
                "row_span": c.row_span,
                "column_span": c.column_span,
                "bounding_regions": [{"page_number": br.page_number, "polygon": br.polygon} for br in c.bounding_regions]
            } for c in t.cells]
        } for t in result.tables],
        "figures": [{
            "bounding_regions": [{"page_number": br.page_number, "polygon": br.polygon} for br in f.bounding_regions]
        } for f in result.figures],
    }
    return layout_elements

import io
from document_client import get_document_intelligence_client

def extract_tables(payload):
    client = get_document_intelligence_client()
    with client:
        poller = client.begin_analyze_document(
            "prebuilt-layout",
            body=io.BytesIO(payload['document_bytes']), 
            content_type=payload['mime_type']
        )
        result = poller.result()

    tables = []
    for table in result.tables:
        cells_data = []
        for cell in table.cells:
            cells_data.append({
                "content": cell.content,
                "row_index": cell.row_index,
                "column_index": cell.column_index,
                "row_span": cell.row_span or 1,
                "column_span": cell.column_span or 1,
            })
        tables.append({
            "row_count": table.row_count,
            "column_count": table.column_count,
            "cells": cells_data
        })
    return {"tables": tables}

import io
from document_client import get_document_intelligence_client

def extract_key_values(payload):
    client = get_document_intelligence_client()
    with client:
        poller = client.begin_analyze_document(
            "prebuilt-document", # prebuilt-document is good for key-value pairs
            body=io.BytesIO(payload['document_bytes']), 
            content_type=payload['mime_type']
        )
        result = poller.result()

    key_value_pairs = []
    if result.key_value_pairs:
        for kv_pair in result.key_value_pairs:
            if kv_pair.key and kv_pair.value:
                key_value_pairs.append({
                    "key": kv_pair.key.content,
                    "value": kv_pair.value.content
                })

    return {"key_value_pairs": key_value_pairs}

import os
from google.cloud import translate_v3 as translate

def ocr_translate(text, target_language_code, project_id=None):
    project_id = project_id or os.environ.get("GOOGLE_CLOUD_PROJECT")
    if not project_id:
        raise ValueError("Google Cloud project ID must be provided or set in GOOGLE_CLOUD_PROJECT environment variable.")

    client = translate.TranslationServiceClient()
    location = "global"
    parent = f"projects/{project_id}/locations/{location}"

    response = client.translate_text(
        request={
            "parent": parent,
            "contents": [text],
            "target_language_code": target_language_code,
        }
    )

    translations = []
    for translation in response.translations:
        translations.append(translation.translated_text)
    return {"translations": translations}

import os
import google.generativeai as genai

def ocr_safety(text, model_name="gemini-pro"): # gemini-pro for content moderation
    genai.configure(api_key=os.environ.get("GOOGLE_API_KEY"))
    model = genai.GenerativeModel(model_name)

    response = model.generate_content(
        f"Analyze the following text for safety and content policy violations. Categorize any issues. Text: {text}"
    )

    # The safety_ratings are part of the candidate, not directly on the response
    safety_ratings_output = []
    for candidate in response.candidates:
        if hasattr(candidate, 'safety_ratings'):
            for rating in candidate.safety_ratings:
                safety_ratings_output.append({
                    "category": rating.category.name,
                    "probability": rating.probability.name,
                })

    # Also include the text output from the model if available
    model_output_text = "No content generated due to safety concerns." 
    if response.candidates and hasattr(response.candidates[0], 'content') and response.candidates[0].content.parts:
        model_output_text = response.candidates[0].content.parts[0].text

    return {"safety_analysis": model_output_text, "safety_ratings": safety_ratings_output}

import os
import google.generativeai as genai

def document_field_extraction(document_text, fields_to_extract, model_name="gemini-pro"): # gemini-pro for structured extraction
    genai.configure(api_key=os.environ.get("GOOGLE_API_KEY"))
    model = genai.GenerativeModel(model_name)

    prompt = f"Extract the following fields from the document text as a JSON object: {', '.join(fields_to_extract)}. Document text: {document_text}"

    response = model.generate_content(prompt)

    extracted_data = {}
    if response.candidates and hasattr(response.candidates[0], 'content') and response.candidates[0].content.parts:
        # Attempt to parse the response as JSON. The model is prompted to return JSON.
        try:
            import json
            extracted_data = json.loads(response.candidates[0].content.parts[0].text)
        except json.JSONDecodeError:
            extracted_data = {"raw_response": response.candidates[0].content.parts[0].text, "error": "Could not parse model output as JSON"}

    return {"extracted_fields": extracted_data}

import os
from google.cloud import aiplatform

def ocr_embedding(text_segments, project_id=None, location="us-central1", model_name="text-embedding-004"):
    project_id = project_id or os.environ.get("GOOGLE_CLOUD_PROJECT")
    if not project_id:
        raise ValueError("Google Cloud project ID must be provided or set in GOOGLE_CLOUD_PROJECT environment variable.")

    aiplatform.init(project=project_id, location=location)

    embedding_model = aiplatform.language_models.TextEmbeddingModel.from_pretrained(model_name)

    embeddings_list = []
    if isinstance(text_segments, str):
        text_segments = [text_segments] # Ensure it's a list for batch prediction

    # The TextEmbeddingModel expects a list of texts
    predictions = embedding_model.predict(text_segments)

    for embedding in predictions.embeddings:
        embeddings_list.append(embedding.values)

    return {"embeddings": embeddings_list}
